          atEvents.push({ kind: "zenigata-super", label: "超逮捕RUSH", games: superGames, addGames: extraGames, award: mainAward + extraAward, cumulative: payout });
          flow.push(`超逮捕RUSH 10G＋30G・上乗せ+${extraGames}G・累計${yen.format(payout)}枚`);
